#!/usr/bin/env node
// sync-copilot-payload.mjs — keep adapters/copilot/.github/omatic/ identical to
// the pack's canonical contracts. --check exits 1 if any vendored copy drifted.
//
// CANONICAL SOURCE: o-matic-studio/studio/scripts/sync-copilot-payload.mjs. The
// copies in o-matic-firm/firm/scripts/ and o-matic-agency/agency/scripts/ are
// generated by o-matic-studio/scripts/sync-pack-tooling.mjs (--check fails on
// drift). What each pack vendors is DATA, in adapters/copilot/payload.json, so
// one script serves all three packs (Smith #1013 F12: three variants of this
// file had drifted apart in their comments and tables).
//
// WHY THIS EXISTS. A Copilot payload is copied into a DIFFERENT workspace. Once
// copied, no relative path back into the pack resolves — under any correction.
// Agency shipped ../../../../ROLE-CORE.md and it resolved nowhere (task #586);
// studio shipped a path that resolved INSIDE the pack and broke only after the
// copy. So `.github/` is self-contained: what it loads travels with it under
// `.github/omatic/`, referenced as `../omatic/<file>`. Vendored copies drift, so
// they are generated, not hand-written, and this script is the control.
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { dirname, join, resolve, basename } from "node:path";
import { fileURLToPath } from "node:url";

const pack = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const name = basename(pack);
const dest = join(pack, "adapters/copilot/.github/omatic");
const manifest = join(pack, "adapters/copilot/payload.json");
const check = process.argv.includes("--check");

if (!existsSync(manifest)) {
  console.error(`NO MANIFEST: ${name}/adapters/copilot/payload.json is missing — nothing defines the payload`);
  process.exit(2);
}
const { files } = JSON.parse(readFileSync(manifest, "utf8"));
if (!Array.isArray(files) || !files.length) {
  console.error(`EMPTY MANIFEST: ${name}/adapters/copilot/payload.json lists no files`);
  process.exit(2);
}

const BANNER = (src) =>
  `<!-- GENERATED COPY — do not edit. Source: ${name}/${src}\n` +
  `     Regenerate with: node ${name}/scripts/sync-copilot-payload.mjs\n` +
  `     This copy exists so adapters/copilot/.github/ stays self-contained when\n` +
  `     it is copied into another workspace. -->\n\n`;

mkdirSync(dest, { recursive: true });
let stale = 0, wrote = 0;
for (const { source, name: out, rewrites = [] } of files) {
  let body = readFileSync(join(pack, source), "utf8");
  for (const [from, to] of rewrites) {
    if (!body.includes(from)) {
      console.error(`SOURCE CHANGED: ${source} no longer contains ${from}`);
      process.exit(2);
    }
    body = body.split(from).join(to);
  }
  const next = BANNER(source) + body;
  const target = join(dest, out);
  const cur = existsSync(target) ? readFileSync(target, "utf8") : null;
  if (cur === next) { console.log(`ok:    ${out}`); continue; }
  stale++;
  if (check) console.log(`STALE: ${out}`);
  else { writeFileSync(target, next); wrote++; console.log(`sync:  ${out}`); }
}
if (check && stale) { console.log(`\n${stale} vendored copy(ies) stale — run without --check`); process.exit(1); }
console.log(check ? "\ncopilot payload in sync" : `\ndone — ${wrote} updated`);
